@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap");
@import url("https://use.typekit.net/iuv1iky.css");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

#app > *,
#root > * {
  width: 100%;
}

#app {
  container-type: inline-size;
}

[font=Inter][weight=normal] {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-style: normal;
}

[fontSize=sm] {
  font-size: 0.75rem;
}

[fontSize=md] {
  font-size: 1.25rem;
}

[fontSize=lg] {
  font-size: 1.5rem;
}

[fontSize=xl] {
  font-size: 2rem;
}

[fontSize=xxl] {
  font-size: 3rem;
}

p[align=center] {
  text-align: center;
}

p[align=right] {
  text-align: right;
}

p[align=justify] {
  text-align: justify;
}

p[decoration=underline] {
  text-decoration: underline;
}

h1 {
  font-size: clamp(1.8rem, 2.5vw, 3rem);
}

h2 {
  font-size: clamp(1.5rem, 2vw, 2.5rem);
}

p {
  font-size: clamp(1rem, 1.5vw, 1.25rem);
}

[grid="2x2"] {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: repeat(2, 1fr);
}

[grid="3x2"] {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, 1fr);
}

[grid="3x3"] {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
}

[grid="4x3"] {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(3, 1fr);
}

[grid="4x4"] {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
}

[span="1"] {
  grid-column: span 1;
}

[span="2"] {
  grid-column: span 2;
}

[span="3"] {
  grid-column: span 3;
}

[span="4"] {
  grid-column: span 4;
}

[span="5"] {
  grid-column: span 5;
}

[span="6"] {
  grid-column: span 6;
}

[span="1"] {
  grid-row: span 1;
}

[span="2"] {
  grid-row: span 2;
}

[span="3"] {
  grid-row: span 3;
}

[span="4"] {
  grid-row: span 4;
}

[span="5"] {
  grid-row: span 5;
}

[span="6"] {
  grid-row: span 6;
}

[gap="1"] {
  gap: 1rem;
}

[gap="2"] {
  gap: 2rem;
}

[gap="3"] {
  gap: 3rem;
}

[gap="4"] {
  gap: 4rem;
}

[gap="5"] {
  gap: 5rem;
}

[gap="6"] {
  gap: 6rem;
}

[gap="7"] {
  gap: 7rem;
}

[gap="8"] {
  gap: 8rem;
}

[gap="9"] {
  gap: 9rem;
}

[gap="10"] {
  gap: 10rem;
}

[position=toBack] {
  position: relative;
  z-index: -1;
}

[position=toFront] {
  position: relative;
  z-index: 1;
}

[position=absolute] {
  position: absolute;
}

:where([stack]) {
  display: flex;
  flex-direction: column !important;
  margin: 0 auto;
}

[stack][reverse] {
  display: flex;
  flex-direction: column-reverse;
}

[stack][centered] {
  margin: 0 auto;
  align-items: center;
  justify-content: center;
}

[row] {
  display: flex;
  flex-direction: row;
}

[row][centered] {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
}

@media (min-width: 768px) {
  [container] {
    padding: 2rem;
    gap: 1.5rem;
  }
}
@media screen and (max-width: 768px) {
  [row] {
    flex-direction: column;
  }
}
@media (min-width: 1024px) {
  [container] {
    padding: 3rem;
    gap: 2rem;
  }
}
@media (min-width: 1536px) {
  [container] {
    max-width: 1280px;
    margin: 0 auto;
  }
}
section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

section > * {
  flex: 1, 1, 100%;
}

@media (min-width: 768px) {
  section {
    flex-direction: row;
    flex-wrap: wrap;
  }
}
@media (min-width: 768px) {
  section {
    flex: 1 1 calc(50% - 1rem);
  }
}
@media (min-width: 1024px) {
  section > * {
    flex: 1 1 calc(33.333% - 1rem);
  }
}
@container (min-width: 600px) {
  section {
    flex-direction: row;
  }
}
[grid] {
  display: grid;
}

[float=left] {
  float: left;
}

[btn=flat] {
  border-style: solid;
}
[btn=flat][theme=citrusmint-300] {
  background: hsl(121, 100%, 70%);
  color: hsl(121, 100%, 40%);
  border-color: hsl(121, 100%, 40%);
}
[btn=flat][theme=citrusmint-300]:hover {
  background: hsl(121, 100%, 40%);
  color: hsl(121, 100%, 90%);
  border-color: hsl(121, 100%, 90%);
}
[btn=flat] [scale=lg] {
  height: 4vh;
  width: 7vw;
  padding: 0.5rem 1rem;
}

form[type=search] [scale=lg] {
  width: 100%;
  height: 6vh;
}

form [field] {
  display: flex;
  flex-direction: row;
}
form [field][stack] {
  display: flex;
  flex-direction: column;
}

nav[type=bar] {
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 10vh;
  width: 100%;
  position: relative;
  overflow: visible;
}
nav[type=bar] ul {
  list-style: none;
  display: flex;
  gap: 2rem;
}
nav[type=bar] ul li {
  list-style: none;
}
nav[type=bar] ul li a {
  text-decoration: none;
}
nav[type=bar][theme=citrusmint-300] {
  background: hsl(121, 100%, 90%);
  color: hsl(121, 100%, 40%);
}
nav[type=bar][theme=citrusmint-300] a {
  color: hsl(121, 100%, 40%);
}
nav[type=bar][theme=citrusmint-300] a:hover {
  color: hsl(121, 100%, 70%);
}

nav[sticky] {
  position: sticky;
  top: 0;
  left: 0;
}

nav[fixed] {
  position: fixed;
  top: 0;
  left: 0;
}

nav[type=footer] {
  display: flex;
  align-items: center;
  justify-content: center;
}
nav[type=footer] ul {
  list-style: none;
  display: flex;
  gap: 2rem;
}
nav[type=footer] ul li {
  list-style: none;
}
nav[type=footer] ul li a {
  text-decoration: none;
  color: inherit;
}

nav[type=strip] {
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 5vh;
  width: 100%;
}
nav[type=strip][gradient=citrusmint-300] {
  background: linear-gradient(90deg, var(--citrusmint-300) 0%, var(--citrusmint-200) 100%);
}

